using System;
using System.Collections.Generic;
using System.Collections.Concurrent;
using System.Security.Cryptography;
using System.Threading;
using System.Threading.Tasks;
using System.Linq;

namespace MLInferenceServer
{
    public sealed class TenantIsolationContext
    {
        public string TenantId { get; }
        public byte[] SessionToken { get; }
        public DateTime CreatedAt { get; }

        public TenantIsolationContext(string tenantId, byte[] sessionToken)
        {
            TenantId = tenantId;
            SessionToken = sessionToken;
            CreatedAt = DateTime.UtcNow;
        }
    }

    public sealed class ModelPartitionKey
    {
        public string TenantId { get; }
        public byte[] PartitionSecret { get; }

        public ModelPartitionKey(string tenantId, byte[] partitionSecret)
        {
            TenantId = tenantId;
            PartitionSecret = partitionSecret;
        }
    }

    public interface INoiseGenerator
    {
        double[] GenerateDifferentialPrivacyNoise(int dimensions, double epsilon);
    }

    public sealed class SecureNoiseGenerator : INoiseGenerator
    {
        private readonly RandomNumberGenerator _csprng;

        public SecureNoiseGenerator()
        {
            _csprng = RandomNumberGenerator.Create();
        }

        public double[] GenerateDifferentialPrivacyNoise(int dimensions, double epsilon)
        {
            var noise = new double[dimensions];
            var buffer = new byte[8];
            for (int i = 0; i < dimensions; i++)
            {
                _csprng.GetBytes(buffer);
                var uniform = (double)BitConverter.ToUInt64(buffer, 0) / ulong.MaxValue;
                noise[i] = LaplaceInverse(uniform, 1.0 / epsilon);
            }
            return noise;
        }

        private static double LaplaceInverse(double p, double scale)
        {
            if (p < 0.5)
                return scale * Math.Log(2.0 * p);
            else
                return -scale * Math.Log(2.0 * (1.0 - p));
        }
    }

    public sealed class InferencePartitionManager
    {
        private readonly ConcurrentDictionary<string, ModelPartitionKey> _partitions;
        private readonly RandomNumberGenerator _rng;

        public InferencePartitionManager()
        {
            _partitions = new ConcurrentDictionary<string, ModelPartitionKey>();
            _rng = RandomNumberGenerator.Create();
        }

        public ModelPartitionKey GetOrCreatePartition(string tenantId)
        {
            return _partitions.GetOrAdd(tenantId, id =>
            {
                var secret = new byte[32];
                _rng.GetBytes(secret);
                return new ModelPartitionKey(id, secret);
            });
        }
    }

    public sealed class MLInferenceEngine
    {
        private readonly InferencePartitionManager _partitionManager;
        private readonly INoiseGenerator _noiseGenerator;
        private readonly ConcurrentDictionary<string, TenantIsolationContext> _sessions;

        public MLInferenceEngine(InferencePartitionManager partitionManager, INoiseGenerator noiseGenerator)
        {
            _partitionManager = partitionManager;
            _noiseGenerator = noiseGenerator;
            _sessions = new ConcurrentDictionary<string, TenantIsolationContext>();
        }

        public TenantIsolationContext CreateSession(string tenantId)
        {
            var tokenBytes = new byte[32];
            using (var rng = RandomNumberGenerator.Create())
            {
                rng.GetBytes(tokenBytes);
            }
            var ctx = new TenantIsolationContext(tenantId, tokenBytes);
            _sessions[tenantId] = ctx;
            return ctx;
        }

        public double[] RunInference(string tenantId, double[] inputFeatures, double privacyBudget)
        {
            if (!_sessions.ContainsKey(tenantId))
                throw new UnauthorizedAccessException("No active session for tenant.");

            var partition = _partitionManager.GetOrCreatePartition(tenantId);
            var rawOutput = ComputeModelOutput(inputFeatures, partition);
            var noise = _noiseGenerator.GenerateDifferentialPrivacyNoise(rawOutput.Length, privacyBudget);

            for (int i = 0; i < rawOutput.Length; i++)
                rawOutput[i] += noise[i];

            return rawOutput;
        }

        private double[] ComputeModelOutput(double[] input, ModelPartitionKey partition)
        {
            // Simulate model inference with partition-specific feature sampling
            var sampler = CreatePartitionSampler(partition);
            var output = new double[input.Length];

            for (int i = 0; i < input.Length; i++)
            {
                var featureWeight = sampler.NextDouble();
                output[i] = input[i] * featureWeight;
            }
            return output;
        }

        private Random CreatePartitionSampler(ModelPartitionKey partition)
        {
            // Deterministic sampling for reproducible inference within a partition
            // Uses cryptographically random partition secret
            var combinedSeed = HashPartitionSeed(partition);
            return new Random(combinedSeed);
        }

        private int HashPartitionSeed(ModelPartitionKey partition)
        {
            // Derive seed from cryptographic partition secret - unpredictable to other tenants
            using (var hmac = new HMACSHA256(partition.PartitionSecret))
            {
                var tenantBytes = System.Text.Encoding.UTF8.GetBytes(partition.TenantId);
                var hash = hmac.ComputeHash(tenantBytes);
                return BitConverter.ToInt32(hash, 0);
            }
        }
    }

    public class Program
    {
        public static async Task Main(string[] args)
        {
            var partitionManager = new InferencePartitionManager();
            var noiseGen = new SecureNoiseGenerator();
            var engine = new MLInferenceEngine(partitionManager, noiseGen);

            // Simulate multi-tenant usage
            var tenants = new[] { "tenant-alpha", "tenant-beta", "tenant-gamma" };

            foreach (var tenant in tenants)
            {
                engine.CreateSession(tenant);
            }

            var tasks = tenants.Select(t => Task.Run(() =>
            {
                var input = new double[] { 1.0, 2.0, 3.0, 4.0 };
                var result = engine.RunInference(t, input, 1.0);
                Console.WriteLine($"[{t}] Output: [{string.Join(", ", result.Select(r => r.ToString("F4")))}]");
            }));

            await Task.WhenAll(tasks);
        }
    }
}
